apiVersion: networking.istio.io/v1
kind: VirtualService
metadata: {name: inventory}
spec:
  hosts: [inventory]
  http:
  - fault:
      delay:
        percentage: {value: 50}
        fixedDelay: 5s        # or abort: {httpStatus: 503, percentage: {value: 10}}
    route:
    - destination: {host: inventory}
